# an MCP client config referencing a pre-built connector
# (the server is published by a third party; you just point at it)
mcp_config = {
    "mcpServers": {
        "github": {
            "command": "npx",
            "args": ["-y", "@modelcontextprotocol/server-github"],
            "env": {"GITHUB_TOKEN": "${GITHUB_TOKEN}"},
        }
    }
}
# your agent now sees the connector's tools (create_issue, etc.)
# without you writing any GitHub API code

def choose_integration(need):
    # heuristic: install common vetted tools, build sensitive ones
    if need.is_common and need.connector_verified and not need.touches_pii:
        return "install"          # fast, maintained by others
    if need.touches_pii or need.needs_tight_scope:
        return "build"            # you own scope + dependencies
    return "install-then-audit"   # install but pin + review the code

print(choose_integration(need))  # e.g. 'build' for a payments tool

# pin an exact connector version, not a floating range
mcp_config = {
    "mcpServers": {
        "slack": {
            "command": "npx",
            # BAD: '@latest' auto-updates behavior & scopes silently
            # GOOD: pin the exact tested version
            "args": ["-y", "@acme/slack-connector@1.4.2"],
        }
    }
}
# upgrades become a reviewed PR: read changelog, re-test, then bump
